Commit:     welpy-cw <h.w.forms@arcor.de>
CommitDate: Wed May 27 11:59:39 2026 +0300

    Bug 355205 - Sanitize IMAP custom keywords before syncing. r=BenC


    If a malformed tag (e.g., from an RSS feed containing an '&' or '>') makes it
    into the local database, syncing that tag to an IMAP server causes the entire
    batch `-FLAGS` or `+FLAGS` command to fail with a BAD Parse Error. This
    creates a permanent state desync between the local DB and the IMAP server.
    Furthermore, the '>' character specifically breaks Thunderbird's internal
    IMAP URL parser.

    This patch introduces a protocol firewall in `nsImapService::StoreCustomKeywords`.
    It tokenizes the requested flags and strictly drops any tokens containing
    characters that violate RFC 3501 atom specifications or internal URL
    delimiters. Valid tags in the batch are safely preserved and synced, while
    malformed tags are silently dropped from the network request.

    Differential Revision: https://phabricator.services.mozilla.com/D302296

diff --git a/mailnews/imap/public/nsIImapService.idl b/mailnews/imap/public/nsIImapService.idl
index b0bca766594..c2112c9c9ed 100644
--- a/mailnews/imap/public/nsIImapService.idl
+++ b/mailnews/imap/public/nsIImapService.idl
@@ -223,6 +223,38 @@ interface nsIImapService : nsISupports
                                  in ACString aAttribute,
                                  in ACString aMessageIdentifierList);

+  /**
+   * Stores custom keywords (tags) for a list of messages on the IMAP server.
+   *
+   * @note Keyword Sanitization & Restrictions
+   * To prevent server parse errors and local state desynchronization, the
+   * keywords provided in flagsToAdd and flagsToSubtract are strictly sanitized.
+   * Any keyword containing invalid characters is silently dropped from the
+   * network request.
+   *
+   * A keyword is deemed invalid if it contains any of the following:
+   * 1. Non-ASCII characters (>= 0x7F) or control characters / spaces (<= 0x20).
+   * 2. RFC 3501 wildcards and quoted-specials: % * " \
+   * 3. Symmetrical Enclosures: ( ) [ ] { }
+   * Note: While '[' and '}' are technically valid atom-chars under RFC 3501,
+   * they are strictly filtered here to prevent UX confusion and to defend
+   * against poorly written IMAP server parsers that trip on unescaped brackets.
+   * 4. Internal URI Delimiters: < > ;
+   * Restricted because Thunderbird uses nsIURI to route IMAP commands internally.
+   * '<' and '>' are Unsafe URI characters (RFC 3986), and '>' specifically
+   * breaks Thunderbird's hardcoded IMAP URL parser. The ';' is restricted as it
+   * is the reserved delimiter for internal URL parameters (e.g., ;SECTION=TEXT).
+   * 5. The '&' character: Restricted because its role as the MUTF-7 shift
+   * character causes parsing crashes on certain strict IMAP servers.
+   *
+   * @param aMailFolder            The IMAP folder containing the messages.
+   * @param aMsgWindow             The message window for status/error reporting.
+   * @param flagsToAdd             Space-separated string of keywords to add.
+   * @param flagsToSubtract        Space-separated string of keywords to remove.
+   * @param aMessageIdentifierList Comma-separated list of message UIDs.
+   *
+   * @return nsIURI                The internal IMAP URL generated for this command.
+   */
   nsIURI storeCustomKeywords(in nsIMsgFolder aMailFolder,
                              in nsIMsgWindow aMsgWindow,
                              in ACString flagsToAdd,
diff --git a/mailnews/imap/src/nsImapService.cpp b/mailnews/imap/src/nsImapService.cpp
index f319921225b..1849b94fe9c 100644
--- a/mailnews/imap/src/nsImapService.cpp
+++ b/mailnews/imap/src/nsImapService.cpp
@@ -59,6 +59,7 @@
 #include "mozilla/Components.h"
 #include "mozilla/LoadInfo.h"
 #include "mozilla/Preferences.h"
+#include "nsWhitespaceTokenizer.h"

 using mozilla::Preferences;
 using mozilla::net::LoadInfo;
@@ -2765,12 +2766,68 @@ NS_IMETHODIMP nsImapService::FetchCustomMsgAttribute(
   return rv;
 }

+namespace {
+
+/**
+ * Strips keywords that contain characters invalid for an IMAP atom (RFC 3501)
+ * or characters that break Thunderbird's internal URL parser (e.g., '>').
+ */
+static void SanitizeKeywords(const nsACString& aKeywords,
+                             nsACString& aSafeKeywords) {
+  aSafeKeywords.Truncate();
+
+  // Parse space-separated keywords
+  bool first = true;
+
+  nsCWhitespaceTokenizer tokenizer(aKeywords);
+  while (tokenizer.hasMoreTokens()) {
+    const nsACString& token = tokenizer.nextToken();
+    if (token.IsEmpty()) {
+      continue;
+    }
+
+    bool isValid = true;
+
+    // Check for specific invalid symbols as defined in RFC 3501 atom-specials,
+    // and also for symbols that break Thunderbird's internal URL parser.
+    // We also exclude the ampersand since it is used in MUTF-7 encoding and
+    // seems to confuse some IMAP servers when used in keywords.
+    for (uint32_t i = 0; i < token.Length(); i++) {
+      unsigned char c = token.CharAt(i);
+      if (mozilla::IsAsciiAlphanumeric(c)) {
+        continue;
+      }
+      if (c <= 0x20 || c >= 0x7F || strchr("()[]{}%*\"\\<>;&", c)) {
+        isValid = false;
+        break;
+      }
+    }
+
+    if (isValid) {
+      if (!first) {
+        aSafeKeywords.Append(' ');
+      }
+      aSafeKeywords.Append(token);
+      first = false;
+    }
+  }
+}
+
+}  // namespace
+
 NS_IMETHODIMP nsImapService::StoreCustomKeywords(
     nsIMsgFolder* anImapFolder, nsIMsgWindow* aMsgWindow,
     const nsACString& flagsToAdd, const nsACString& flagsToSubtract,
     const nsACString& uids, nsIURI** aURL) {
   NS_ENSURE_ARG_POINTER(anImapFolder);

+  // Ensure bad tags from RSS feeds or legacy databases cannot crash the IMAP
+  // socket or break the internal '>' URL parser.
+  nsAutoCString safeFlagsToAdd;
+  nsAutoCString safeFlagsToSubtract;
+  SanitizeKeywords(flagsToAdd, safeFlagsToAdd);
+  SanitizeKeywords(flagsToSubtract, safeFlagsToSubtract);
+
   nsCOMPtr<nsIImapUrl> imapUrl;
   nsAutoCString urlSpec;
   nsresult rv;
@@ -2796,12 +2853,13 @@ NS_IMETHODIMP nsImapService::StoreCustomKeywords(
       urlSpec.Append('>');
       urlSpec.Append(uids);
       urlSpec.Append('>');
-      urlSpec.Append(flagsToAdd);
+      urlSpec.Append(safeFlagsToAdd);
       urlSpec.Append('>');
-      urlSpec.Append(flagsToSubtract);
+      urlSpec.Append(safeFlagsToSubtract);
       rv = mailNewsUrl->SetSpecInternal(urlSpec);
-      if (NS_SUCCEEDED(rv))
+      if (NS_SUCCEEDED(rv)) {
         rv = GetImapConnectionAndLoadUrl(imapUrl, nullptr, aURL);
+      }
     }
   }  // if we have a url to run....
